PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE appointments (
	id VARCHAR(36) NOT NULL, 
	patient_id VARCHAR(36) NOT NULL, 
	doctor_id VARCHAR(36) NOT NULL, 
	slot_id VARCHAR(36), 
	assistant_id VARCHAR(36), 
	status VARCHAR(40) NOT NULL, 
	slip_number VARCHAR(50), 
	patient_name VARCHAR(120), 
	patient_phone VARCHAR(30), 
	notes TEXT, 
	reschedule_reason TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, patient_email VARCHAR(255), 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES users (id), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id), 
	FOREIGN KEY(slot_id) REFERENCES doctor_slots (id), 
	FOREIGN KEY(assistant_id) REFERENCES users (id)
);
CREATE TABLE audit_logs (
	id VARCHAR(36) NOT NULL, 
	actor_id VARCHAR(36), 
	action VARCHAR(50) NOT NULL, 
	entity VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(100), 
	before_value TEXT, 
	after_value TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(actor_id) REFERENCES users (id)
);
CREATE TABLE doctor_assistants (
	doctor_id VARCHAR(36) NOT NULL, 
	assistant_user_id VARCHAR(36) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (doctor_id, assistant_user_id), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE CASCADE, 
	FOREIGN KEY(assistant_user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE TABLE doctor_reviews (
	id VARCHAR(36) NOT NULL, 
	doctor_id VARCHAR(36) NOT NULL, 
	appointment_id VARCHAR(36) NOT NULL, 
	patient_name VARCHAR(120) NOT NULL, 
	patient_phone VARCHAR(30) NOT NULL, 
	rating INTEGER NOT NULL, 
	comment TEXT NOT NULL, 
	tags VARCHAR(255), 
	is_verified BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE CASCADE, 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE CASCADE
);
CREATE TABLE doctor_slots (
	id VARCHAR(36) NOT NULL, 
	doctor_id VARCHAR(36) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_doctor_slot_concurrency UNIQUE (doctor_id, start_time), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE CASCADE
);
CREATE TABLE doctors (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	specialty VARCHAR(100) NOT NULL, 
	sub_region VARCHAR(100) NOT NULL, 
	clinic_address TEXT NOT NULL, 
	google_maps_url TEXT, 
	fee_clinic NUMERIC(10, 2) NOT NULL, 
	shift VARCHAR(20) NOT NULL, 
	morning_start VARCHAR(10) NOT NULL, 
	morning_end VARCHAR(10) NOT NULL, 
	evening_start VARCHAR(10) NOT NULL, 
	evening_end VARCHAR(10) NOT NULL, 
	is_spotlight BOOLEAN NOT NULL, 
	verification_status VARCHAR(20) NOT NULL, 
	profile_image VARCHAR(500), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, off_days TEXT DEFAULT 'friday,sunday', bio TEXT, expertise VARCHAR(255), experience_years INTEGER DEFAULT 5, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
','https://maps.app.goo.gl/fPD3ta1KUqZXRBfb8',1000,'EVENING','09:00','13:00','17:00','21:00',1,'verified',NULL,'2026-10-07 18:39:55.297278','2026-10-07 18:39:55.297286','friday,sunday',NULL,NULL,12);
CREATE TABLE payments (
	id VARCHAR(36) NOT NULL, 
	appointment_id VARCHAR(36) NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	paid_at DATETIME, 
	collected_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (appointment_id), 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE CASCADE, 
	FOREIGN KEY(collected_by) REFERENCES users (id)
);
CREATE TABLE users (
	id VARCHAR(36) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	phone VARCHAR(20) NOT NULL, 
	whatsapp_number VARCHAR(20), 
	password_hash VARCHAR(255), 
	plain_password VARCHAR(255), 
	role VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_users_phone ON users (phone);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_doctors_specialty ON doctors (specialty);
CREATE INDEX ix_doctors_sub_region ON doctors (sub_region);
CREATE INDEX ix_doctors_is_spotlight ON doctors (is_spotlight);
CREATE INDEX ix_audit_logs_actor_id ON audit_logs (actor_id);
CREATE INDEX ix_doctor_slots_doctor_id ON doctor_slots (doctor_id);
CREATE INDEX ix_appointments_status ON appointments (status);
CREATE UNIQUE INDEX ix_appointments_slip_number ON appointments (slip_number);
CREATE INDEX ix_appointments_doctor_id ON appointments (doctor_id);
CREATE INDEX ix_appointments_patient_id ON appointments (patient_id);
CREATE INDEX ix_payments_status ON payments (status);
CREATE INDEX ix_doctor_reviews_doctor_id ON doctor_reviews (doctor_id);
CREATE UNIQUE INDEX ix_doctor_reviews_appointment_id ON doctor_reviews (appointment_id);
COMMIT;
